from pathlib import Path
import json,re
base=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
task="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
patterns=("usage limit","try again","retry","limit","quota")
hits=[]
for p in [base/"models/STATE.json",base/"models/CONTINUATION.json",base/"models/BLOCKER.json"]:
    if p.is_file():
        txt=p.read_text(encoding="utf-8",errors="replace")
        for line in txt.splitlines():
            if any(x in line.lower() for x in patterns):
                hits.append({"source":str(p),"line":line[:1200]})
runs=base/"runs"
if runs.is_dir():
    for p in sorted(runs.rglob("*"), key=lambda x:x.stat().st_mtime if x.exists() else 0, reverse=True)[:200]:
        if not p.is_file(): continue
        if task not in str(p) and "389ea715" not in str(p): continue
        try: txt=p.read_text(encoding="utf-8",errors="replace")
        except Exception: continue
        for line in txt.splitlines():
            if any(x in line.lower() for x in patterns):
                hits.append({"source":str(p),"line":line[:1200]})
print("ERROR_CLASS=R4P2_ASTRA_USAGE_SOURCE",flush=True)
print("ERROR="+json.dumps(hits[-40:],separators=(",",":"),sort_keys=True),flush=True)
raise SystemExit(1)
